def top_paths(entries, n=3):
    from urllib.parse import urlparse
    from collections import Counter

    path_counts = Counter()

    for entry in entries:
        parsed_url = urlparse(entry)
        path = parsed_url.path
        path_counts[path] += 1

    return path_counts.most_common(n)

